// claude_chat_export.js
// Paste into the browser DevTools console on an OPEN Claude.ai conversation.
// Local Blob download only, no network egress.
//
// What changed vs. the original:
//   1. Turn segmentation no longer depends on container.children. It queries
//      the proven message anchors in document order and labels each by role.
//      This is the fix for the "everything under one Human header" failure.
//   2. Whitespace-safe joining: a newline is inserted between adjacent BLOCK
//      children so sibling blocks stop fusing ("May 23The...", "DoneThe...").
//      Inline runs are left untouched so "co"+"operate" style splits can't
//      gain spurious spaces.
//   3. Loud, not silent: turn counts print to the console and the failure
//      case (zero matches) aborts with a message instead of emitting a
//      plausible-looking but empty/broken file.
//   4. Extended thinking captured as a delimited > [thinking] blockquote,
//      with UI chrome (date label, "Thought for ...", "Done") stripped.
//   5. Optional artifact-panel capture via a hook you set after inspecting.
//
// If capture looks incomplete, run the short diagnostic snippet first (see the
// chat message) and adjust the SEL.* selectors below to match the live DOM.

(() => {
  'use strict';

  // ---- Config: adjust only if the diagnostic shows a mismatch ----
  const SEL = {
    userMessage: '[data-testid="user-message"]',
    assistantMessage: '.font-claude-message',
    // Set this if the structural heuristic below fails to find thinking.
    // Find it via the diagnostic, or right-click the "Thought for ..." panel
    // > Inspect and copy a stable class or data-testid.
    thinking: null,          // e.g. '[data-testid="thinking-block"]'
    // Set this to also capture the CURRENTLY OPEN artifact side panel.
    artifactPanel: null,     // e.g. '[data-testid="artifact-panel"]'
  };
  const INCLUDE_THINKING = true;   // false = messages only, no reasoning

  const BLOCK = new Set(['p','div','section','article','ul','ol','li','pre',
    'blockquote','h1','h2','h3','h4','h5','h6','table','tr','hr','header','footer']);

  // ---- HTML -> Markdown ----
  function renderChildren(node) {
    let out = '';
    let prevBlock = false;
    node.childNodes.forEach((child) => {
      const isBlock = child.nodeType === Node.ELEMENT_NODE &&
                      BLOCK.has(child.tagName.toLowerCase());
      const piece = htmlToMd(child);
      if (!piece) return;
      // Separate adjacent block siblings that would otherwise concatenate.
      if ((isBlock || prevBlock) && out && !/\s$/.test(out) && !/^\s/.test(piece)) {
        out += '\n';
      }
      out += piece;
      prevBlock = isBlock;
    });
    return out;
  }

  function htmlToMd(node) {
    if (!node) return '';
    if (node.nodeType === Node.TEXT_NODE) return node.textContent;
    if (node.nodeType !== Node.ELEMENT_NODE) return '';

    const tag = node.tagName.toLowerCase();
    if (['svg','button','style','script','noscript'].includes(tag)) return '';
    if (node.classList && (node.classList.contains('sr-only') ||
        node.classList.contains('hidden'))) return '';

    switch (tag) {
      case 'h1': return `\n# ${renderChildren(node).trim()}\n\n`;
      case 'h2': return `\n## ${renderChildren(node).trim()}\n\n`;
      case 'h3': return `\n### ${renderChildren(node).trim()}\n\n`;
      case 'h4': return `\n#### ${renderChildren(node).trim()}\n\n`;
      case 'h5': return `\n##### ${renderChildren(node).trim()}\n\n`;
      case 'h6': return `\n###### ${renderChildren(node).trim()}\n\n`;
      case 'p':  return `${renderChildren(node).trim()}\n\n`;
      case 'br': return '\n';
      case 'strong': case 'b': return `**${renderChildren(node)}**`;
      case 'em': case 'i': return `*${renderChildren(node)}*`;
      case 'code':
        if (node.parentElement && node.parentElement.tagName.toLowerCase() === 'pre')
          return node.textContent;
        return `\`${node.textContent}\``;
      case 'pre': {
        const codeEl = node.querySelector('code');
        const lang = codeEl
          ? (Array.from(codeEl.classList).find(c => c.startsWith('language-')) || '')
              .replace('language-', '')
          : '';
        const text = (codeEl ? codeEl.textContent : node.textContent) || '';
        return `\n\`\`\`${lang}\n${text.replace(/\n+$/, '')}\n\`\`\`\n\n`;
      }
      case 'ul':
        return '\n' + Array.from(node.children)
          .map(li => `- ${htmlToMd(li).trim().replace(/\n/g, '\n  ')}`)
          .join('\n') + '\n\n';
      case 'ol':
        return '\n' + Array.from(node.children)
          .map((li, i) => `${i + 1}. ${htmlToMd(li).trim().replace(/\n/g, '\n   ')}`)
          .join('\n') + '\n\n';
      case 'li': return renderChildren(node).trim();
      case 'a': {
        const href = node.getAttribute('href') || '';
        const label = renderChildren(node).trim() || href;
        return `[${label}](${href}) `; // trailing space so adjacent links don't fuse
      }
      case 'blockquote':
        return `\n> ${renderChildren(node).trim().replace(/\n/g, '\n> ')}\n\n`;
      case 'hr': return `\n---\n\n`;
      case 'table': {
        const rows = Array.from(node.querySelectorAll('tr'));
        if (!rows.length) return '';
        const cells = tr => Array.from(tr.querySelectorAll('th,td')).map(c => c.textContent.trim());
        const head = cells(rows[0]);
        let out = '\n| ' + head.join(' | ') + ' |\n| ' + head.map(() => '---').join(' | ') + ' |\n';
        for (let i = 1; i < rows.length; i++) out += '| ' + cells(rows[i]).join(' | ') + ' |\n';
        return out + '\n';
      }
      default: return renderChildren(node);
    }
  }

  // ---- Best-effort thinking capture ----
  function findThinking(assistantEl) {
    if (!INCLUDE_THINKING) return '';
    let node = null;

    if (SEL.thinking) {
      // nearest thinking node that precedes this assistant message
      for (const t of document.querySelectorAll(SEL.thinking)) {
        if (t.compareDocumentPosition(assistantEl) & Node.DOCUMENT_POSITION_FOLLOWING) node = t;
      }
    }
    if (!node) {
      // structural fallback: a preceding sibling that is a <details> or whose
      // header text mentions "thought"/"thinking"
      const candidates = [];
      let p = assistantEl;
      for (let d = 0; d < 3 && p; d++, p = p.parentElement) {
        let sib = p.previousElementSibling;
        while (sib) { candidates.push(sib); sib = sib.previousElementSibling; }
      }
      node = candidates.find(el =>
        el.tagName.toLowerCase() === 'details' ||
        /thought|thinking/i.test(((el.querySelector('button,summary,h2,h3') || {}).textContent) || ''));
    }
    if (!node) return '';

    let md = htmlToMd(node).trim();
    // strip leading UI chrome: month-day label, "Thought[ for ...]", "Done"
    md = md.replace(
      /^\s*(?:(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{1,2}|Thought(?: for)?[^\n]*|Done)\s*/,
      '').trim();
    if (!md) return '';
    return '> **[thinking]**\n>\n' + md.split('\n').map(l => '> ' + l).join('\n') + '\n\n';
  }

  // ---- Collect turns in document order ----
  const nodes = Array.from(document.querySelectorAll(`${SEL.userMessage}, ${SEL.assistantMessage}`));
  if (!nodes.length) {
    console.error('[export] No message nodes matched. Selectors are stale — run the diagnostic and update SEL.*');
    return;
  }

  const titleEl = document.querySelector('[data-testid="chat-title-button"]') || document.querySelector('title');
  const title = (titleEl ? titleEl.textContent : 'Claude Conversation').replace(/-\s*Claude\s*$/, '').trim();

  let md = `# ${title}\n\n*Exported ${new Date().toISOString()}*  \n*URL: ${location.href}*\n\n---\n\n`;
  let nUser = 0, nAsst = 0;

  for (const node of nodes) {
    const isUser = node.matches(SEL.userMessage) || !!node.querySelector(SEL.userMessage);
    if (isUser) {
      const text = htmlToMd(node).trim();
      if (!text) continue;
      nUser++;
      md += `## 🧑 Human\n\n${text}\n\n---\n\n`;
    } else {
      const think = findThinking(node);
      const text = htmlToMd(node).trim();
      if (!text && !think) continue;
      nAsst++;
      md += `## 🤖 Claude\n\n${think}${text}\n\n---\n\n`;
    }
  }

  if (SEL.artifactPanel) {
    const panel = document.querySelector(SEL.artifactPanel);
    if (panel) md += `## 📎 Artifact panel (currently open)\n\n${htmlToMd(panel).trim()}\n\n---\n\n`;
  }

  md = md.replace(/\n{3,}/g, '\n\n');

  console.log(
    `[export] captured — Human: ${nUser}, Claude: ${nAsst}. ` +
    `Compare to the visible conversation. If a count is low, scroll to the very top, ` +
    `wait for load, and re-run.`
  );

  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([md], { type: 'text/markdown;charset=utf-8' }));
  a.download = (title.replace(/[^a-z0-9]+/gi, '_').toLowerCase() || 'claude_chat') + '.md';
  a.click();
})();

