// claude_chat_export_api.js
// Paste into the browser DevTools console on an OPEN Claude.ai conversation.
//
// Reads the conversation from the same backend endpoint the web app uses to
// render it, then writes Markdown and downloads it locally. The only network
// call is a same-origin request to Claude's own API for YOUR OWN conversation,
// with your existing session cookie. Nothing is sent anywhere else.
//
// Why this beats the DOM scraper:
//   - No HTML: no selector drift, no whitespace fusion, no markdown guessing.
//   - No lazy-load truncation: the endpoint returns the full message tree
//     regardless of what is scrolled into view.
//   - Block types are labeled in the payload, so thinking, tool calls, and
//     tool results are distinguished exactly instead of reconstructed.
//
// Known caveats:
//   - Undocumented internal endpoint; the URL/params can change without notice.
//     Failures are loud (bad status or a shape mismatch logged to console).
//   - Field names below (sender/content/thinking/parent_message_uuid/...) are
//     inferred. Anything unrecognized is DUMPED as raw JSON rather than dropped,
//     and the first message's shape is logged so you can adjust the accessors.

(async () => {
  'use strict';

  // ------------------------- Config -------------------------
  const MODE = 'active';          // 'active' = the current conversation path only
                                  // 'all'    = every branch (edited/regenerated
                                  //            turns included), nothing pruned
  const INCLUDE_THINKING = true;  // false to omit reasoning blocks
  const STRING_CAP = 20000;       // per-string char cap for tool payloads and raw
                                  // dumps (prevents base64/page-text bloat).
                                  // Truncation is marked, not silent. 0 disables.
  // ----------------------------------------------------------

  const readCookie = (name) => {
    const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + name + '=([^;]+)'));
    if (!m) return null;
    try { return decodeURIComponent(m[1]); } catch { return m[1]; }
  };
  const pick = (obj, ...keys) => {
    for (const k of keys) if (obj && obj[k] !== undefined && obj[k] !== null) return obj[k];
    return undefined;
  };
  const cap = (s) => {
    if (typeof s !== 'string' || !STRING_CAP || s.length <= STRING_CAP) return s;
    return s.slice(0, STRING_CAP) + `\n…[truncated ${s.length - STRING_CAP} chars]`;
  };
  const jsonSafe = (v) => { try { return cap(JSON.stringify(v, null, 2)); } catch { return String(v); } };
  const fence = (label, body, lang = 'json') =>
    `\`\`\`${lang}\n${label ? '// ' + label + '\n' : ''}${body}\n\`\`\`\n\n`;

  // ---------------------- Locate IDs ------------------------
  const convId = location.pathname.split('/').filter(Boolean).pop();
  if (!/^[0-9a-f-]{36}$/i.test(convId || '')) {
    alert('This does not look like a conversation page (no conversation UUID in the URL).');
    return;
  }
  let orgId = readCookie('lastActiveOrg');
  if (!orgId) {
    try {
      const orgs = await (await fetch('/api/organizations', { credentials: 'include' })).json();
      orgId = pick((Array.isArray(orgs) ? orgs[0] : orgs) || {}, 'uuid', 'id');
    } catch { /* ignore, handled below */ }
  }
  if (!orgId) {
    alert('Could not determine the organization ID (lastActiveOrg cookie missing and /api/organizations failed).');
    return;
  }

  // ------------------------- Fetch --------------------------
  const url = `/api/organizations/${orgId}/chat_conversations/${convId}` +
              `?tree=true&rendering_mode=messages&render_all_tools=true`;
  console.log('[export] fetching', url);
  let data;
  try {
    const res = await fetch(url, { credentials: 'include', headers: { 'Content-Type': 'application/json' } });
    if (!res.ok) {
      alert(`API error ${res.status}. If 403, the organization ID is likely wrong for this chat.`);
      return;
    }
    data = await res.json();
  } catch (e) {
    console.error('[export] fetch failed', e);
    alert('Fetch failed. See console.');
    return;
  }

  const messages = pick(data, 'chat_messages', 'messages');
  if (!Array.isArray(messages)) {
    console.error('[export] no message array found. Top-level keys:', Object.keys(data || {}));
    alert('Unexpected payload shape. The console lists the top-level keys so the accessors can be adjusted.');
    return;
  }
  console.log('[export] messages in payload:', messages.length);
  console.log('[export] first message shape (first 1000 chars):', jsonSafe(messages[0]).slice(0, 1000));

  // ----------------------- Ordering -------------------------
  const idOf     = (m) => pick(m, 'uuid', 'id', 'message_id');
  const parentOf = (m) => pick(m, 'parent_message_uuid', 'parent_uuid', 'parent');
  const threaded = messages.some(m => parentOf(m));

  function activePath(list) {
    if (!threaded) return list;                    // already linear
    const byId = new Map(list.map(m => [idOf(m), m]));
    const parents = new Set(list.map(parentOf).filter(Boolean));
    const leaf = [...list].reverse().find(m => !parents.has(idOf(m))) || list[list.length - 1];
    const path = [], seen = new Set();
    for (let m = leaf; m && !seen.has(idOf(m)); m = byId.get(parentOf(m))) {
      seen.add(idOf(m));
      path.push(m);
    }
    return path.reverse();
  }

  let ordered;
  if (MODE === 'all') {
    ordered = messages;
  } else {
    ordered = activePath(messages);
    if (threaded && messages.length > 1 && ordered.length <= 1) {
      console.warn('[export] active-path reconstruction collapsed to <=1 message; the parent/id ' +
                   'field names probably differ. Falling back to full array order (nothing dropped). ' +
                   'Adjust idOf/parentOf using the logged first-message shape.');
      ordered = messages;
    }
  }

  // ------------------------ Render --------------------------
  function renderBlock(block) {
    if (!block || typeof block !== 'object') return '';
    switch (block.type) {
      case 'text':
        return block.text ? `${block.text}\n\n` : '';
      case 'thinking':
        if (!INCLUDE_THINKING || !block.thinking) return '';
        return '> **[thinking]**\n>\n' +
               block.thinking.trim().split('\n').map(l => '> ' + l).join('\n') + '\n\n';
      case 'tool_use':
        return fence(`tool_use: ${block.name || 'unknown'}`, jsonSafe(pick(block, 'input') ?? {}));
      case 'tool_result':
        return fence('tool_result', jsonSafe(pick(block, 'content') ?? block));
      case 'image': {
        const src = block.source || {};
        return `> **[image omitted]** ${src.media_type || ''} ` +
               `(${((src.data || '') + '').length} base64 chars)\n\n`;
      }
      default:
        return fence(`unhandled block type: ${block.type}`, jsonSafe(block));
    }
  }

  function renderAttachments(msg) {
    const atts = pick(msg, 'attachments', 'files');
    if (!Array.isArray(atts) || !atts.length) return '';
    let out = '';
    for (const a of atts) {
      const name = pick(a, 'file_name', 'name', 'title') || 'attachment';
      const extracted = pick(a, 'extracted_content', 'text', 'content');
      out += `> **[attachment: ${name}]**\n\n`;
      if (typeof extracted === 'string' && extracted.trim()) {
        out += fence(`extracted from ${name}`, cap(extracted), 'text');
      } else if (extracted !== undefined) {
        out += fence(`attachment metadata: ${name}`, jsonSafe(a));
      }
    }
    return out;
  }

  const title = pick(data, 'name', 'title') || 'Claude Conversation';
  let md = `# ${title}\n\n` +
           `*Exported ${new Date().toISOString()}*  \n` +
           `*URL: ${location.href}*  \n` +
           `*Mode: ${MODE} • messages: ${ordered.length}` +
           `${MODE === 'active' && threaded ? ` of ${messages.length} in tree` : ''}*\n\n---\n\n`;

  let nUser = 0, nAsst = 0, nOther = 0;
  for (const msg of ordered) {
    const sender = pick(msg, 'sender', 'role');
    const isUser = sender === 'human' || sender === 'user';
    if (isUser) nUser++;
    else if (sender === 'assistant') nAsst++;
    else nOther++;

    const header = isUser ? '## 🧑 Human'
                 : sender === 'assistant' ? '## 🤖 Claude'
                 : `## ⚙️ ${sender || 'unknown'}`;
    md += `${header}\n\n`;

    const ts = pick(msg, 'created_at', 'created', 'timestamp');
    if (ts) md += `*${ts}*\n\n`;

    md += renderAttachments(msg);

    const content = pick(msg, 'content');
    if (Array.isArray(content)) {
      for (const block of content) md += renderBlock(block);
    } else if (typeof pick(msg, 'text') === 'string') {
      md += `${msg.text}\n\n`;
    } else if (content !== undefined) {
      md += fence('unhandled content shape', jsonSafe(content));
    }
    md += `---\n\n`;
  }

  md = md.replace(/\n{4,}/g, '\n\n\n');

  console.log(`[export] rendered — Human: ${nUser}, Claude: ${nAsst}` +
              (nOther ? `, other/system: ${nOther}` : '') +
              '. Compare against the conversation you can see; if a count looks low, ' +
              'the payload may be paginated (check messages.length above).');

  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([md], { type: 'text/markdown;charset=utf-8' }));
  a.download = (title.replace(/[^a-z0-9]+/gi, '_').toLowerCase() || 'claude_chat') + '.md';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
  console.log('[export] done:', a.download);
})();

