// claude_project_batch_export.js
// Paste into DevTools console while logged into Claude.ai. Enumerates the
// conversations in a Project and exports them in ONE pass, reusing the same
// per-conversation fetch/render validated on a single chat.
//
// Output is at most two downloads (no multi-download storm):
//   - <slug>.json : lossless archive — every raw conversation payload + a manifest
//   - <slug>.md   : one concatenated, readable Markdown file with a table of contents
// The JSON is the archive of record; the Markdown is the human-readable view.
//
// CONFIRMED vs INFERRED: only the per-conversation endpoint is confirmed. The
// LIST endpoint, its pagination, and the project-membership field are inferred.
// Run the discovery snippet first. This script logs every count and every
// failure, dumps unknown block types as raw JSON, and stops paginating when a
// page adds nothing new — so the failure modes are visible, not silent.

(async () => {
  'use strict';

  // ------------------------- Config -------------------------
  const PROJECT_ID = '';          // blank = auto-detect from URL / current chat; set to override
  const OUTPUT = 'both';          // 'json' | 'markdown' | 'both'
  const DELAY_MS = 400;           // pause between conversation fetches (rate-limit politeness)
  const INCLUDE_THINKING = true;
  const STRING_CAP = 20000;       // per-string char cap for tool payloads/dumps; 0 = uncapped
  const MAX_PAGES = 50;           // hard stop for list pagination
  // ----------------------------------------------------------

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const readCookie = (name) => {
    const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + name + '=([^;]+)'));
    if (!m) return null;
    try { return decodeURIComponent(m[1]); } catch { return m[1]; }
  };
  const pick = (obj, ...keys) => { for (const k of keys) if (obj && obj[k] != null) return obj[k]; return undefined; };
  const cap = (s) => (typeof s === 'string' && STRING_CAP && s.length > STRING_CAP)
    ? s.slice(0, STRING_CAP) + `\n…[truncated ${s.length - STRING_CAP} chars]` : s;
  const jsonSafe = (v) => { try { return cap(JSON.stringify(v, null, 2)); } catch { return String(v); } };
  const fence = (label, body, lang = 'json') => `\`\`\`${lang}\n${label ? '// ' + label + '\n' : ''}${body}\n\`\`\`\n\n`;

  const api = async (path) => {
    const res = await fetch(path, { credentials: 'include', headers: { 'Content-Type': 'application/json' } });
    if (!res.ok) throw new Error(`${res.status} on ${path}`);
    return res.json();
  };
  const download = (name, text, mime) => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([text], { type: mime + ';charset=utf-8' }));
    a.download = name;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(a.href);
  };

  // ---------------------- Resolve org -----------------------
  let orgId = readCookie('lastActiveOrg');
  if (!orgId) {
    try { const o = await api('/api/organizations'); orgId = pick((Array.isArray(o) ? o[0] : o) || {}, 'uuid', 'id'); } catch {}
  }
  if (!orgId) { alert('Could not determine organization ID.'); return; }
  const ORG = `/api/organizations/${orgId}`;

  // -------------------- Resolve project ---------------------
  let projectId = PROJECT_ID;
  if (!projectId) {
    const mUrl = location.pathname.match(/\/project\/([0-9a-f-]{36})/i);
    if (mUrl) projectId = mUrl[1];
  }
  if (!projectId) {
    const mChat = location.pathname.match(/\/chat\/([0-9a-f-]{36})/i);
    if (mChat) {
      try {
        const c = await api(`${ORG}/chat_conversations/${mChat[1]}`);
        projectId = pick(c, 'project_uuid', 'project_id') || pick(pick(c, 'project') || {}, 'uuid', 'id');
      } catch {}
    }
  }
  if (!projectId) {
    try {
      const pj = await api(`${ORG}/projects`);
      const list = Array.isArray(pj) ? pj : (pick(pj, 'data', 'projects') || []);
      console.log('[batch] no project id resolved. Your projects:',
        list.map(p => ({ id: pick(p, 'uuid', 'id'), name: pick(p, 'name', 'title') })));
      alert('Could not resolve a project id. The console lists your projects; set PROJECT_ID and re-run.');
    } catch (e) { console.error(e); alert('Could not resolve or list projects. See console.'); }
    return;
  }
  console.log('[batch] project:', projectId);

  // ------------------ List conversations --------------------
  async function listConversations() {
    const out = [], seen = new Set();
    let cursor = null;
    for (let page = 0; page < MAX_PAGES; page++) {
      const qs = new URLSearchParams({ limit: '100' });
      if (cursor) qs.set('before', cursor);
      let resp;
      try { resp = await api(`${ORG}/chat_conversations?${qs}`); }
      catch (e) { console.warn('[batch] list fetch failed:', e.message); break; }
      const arr = Array.isArray(resp) ? resp : (pick(resp, 'data', 'conversations', 'chat_conversations') || []);
      if (page === 0) console.log('[batch] list response shape:',
        Array.isArray(resp) ? `array(${arr.length})` : Object.keys(resp || {}));
      let added = 0;
      for (const c of arr) {
        const id = pick(c, 'uuid', 'id');
        if (id && !seen.has(id)) { seen.add(id); out.push(c); added++; }
      }
      if (!arr.length || added === 0) break;                 // no progress -> stop (also kills dup loops)
      const next = pick(resp, 'next_cursor', 'next', 'cursor');
      cursor = next || (arr.length >= 100 ? pick(arr[arr.length - 1], 'updated_at', 'created_at') : null);
      if (!cursor) break;
    }
    return out;
  }

  const all = await listConversations();
  console.log('[batch] conversations visible in org:', all.length);

  const projField = (c) => pick(c, 'project_uuid', 'project_id') || pick(pick(c, 'project') || {}, 'uuid', 'id');
  const hasProjField = all.some(c => projField(c) !== undefined);
  const convos = hasProjField ? all.filter(c => projField(c) === projectId) : all;
  if (!hasProjField) {
    console.warn('[batch] conversations carry no project field under the names tried; cannot filter. ' +
                 'Exporting ALL org conversations. Inspect one item and set the project accessor to filter.');
  }
  console.log(`[batch] conversations to export: ${convos.length}`);
  if (!convos.length) { alert('No conversations matched. See console.'); return; }

  // -------- per-conversation render (validated single-chat logic) --------
  const idOf = (m) => pick(m, 'uuid', 'id', 'message_id');
  const parentOf = (m) => pick(m, 'parent_message_uuid', 'parent_uuid', 'parent');
  function activePath(list) {
    if (!list.some(parentOf)) return list;
    const byId = new Map(list.map(m => [idOf(m), m]));
    const parents = new Set(list.map(parentOf).filter(Boolean));
    const leaf = [...list].reverse().find(m => !parents.has(idOf(m))) || list[list.length - 1];
    const path = [], seen = new Set();
    for (let m = leaf; m && !seen.has(idOf(m)); m = byId.get(parentOf(m))) { seen.add(idOf(m)); path.push(m); }
    return path.reverse();
  }
  function renderBlock(b) {
    if (!b || typeof b !== 'object') return '';
    switch (b.type) {
      case 'text': return b.text ? `${b.text}\n\n` : '';
      case 'thinking': return (!INCLUDE_THINKING || !b.thinking) ? '' :
        '> **[thinking]**\n>\n' + b.thinking.trim().split('\n').map(l => '> ' + l).join('\n') + '\n\n';
      case 'tool_use': return fence(`tool_use: ${b.name || 'unknown'}`, jsonSafe(pick(b, 'input') ?? {}));
      case 'tool_result': return fence('tool_result', jsonSafe(pick(b, 'content') ?? b));
      case 'image': { const s = b.source || {}; return `> **[image omitted]** ${s.media_type || ''} (${((s.data || '') + '').length} b64 chars)\n\n`; }
      default: return fence(`unhandled block type: ${b.type}`, jsonSafe(b));
    }
  }
  function renderAttachments(msg) {
    const atts = pick(msg, 'attachments', 'files');
    if (!Array.isArray(atts) || !atts.length) return '';
    let out = '';
    for (const a of atts) {
      const name = pick(a, 'file_name', 'name', 'title') || 'attachment';
      const ex = pick(a, 'extracted_content', 'text', 'content');
      out += `> **[attachment: ${name}]**\n\n`;
      if (typeof ex === 'string' && ex.trim()) out += fence(`extracted from ${name}`, cap(ex), 'text');
      else if (ex !== undefined) out += fence(`attachment metadata: ${name}`, jsonSafe(a));
    }
    return out;
  }
  function renderConversation(data) {
    const msgs = pick(data, 'chat_messages', 'messages') || [];
    const ordered = activePath(msgs);
    const title = pick(data, 'name', 'title') || 'Untitled';
    let md = `# ${title}\n\n*conversation ${pick(data, 'uuid', 'id') || ''}*  \n*messages: ${ordered.length}*\n\n`;
    for (const msg of ordered) {
      const sender = pick(msg, 'sender', 'role');
      const isUser = sender === 'human' || sender === 'user';
      md += (isUser ? '## 🧑 Human' : sender === 'assistant' ? '## 🤖 Claude' : `## ⚙️ ${sender || 'unknown'}`) + '\n\n';
      const ts = pick(msg, 'created_at', 'created', 'timestamp'); if (ts) md += `*${ts}*\n\n`;
      md += renderAttachments(msg);
      const content = pick(msg, 'content');
      if (Array.isArray(content)) for (const blk of content) md += renderBlock(blk);
      else if (typeof pick(msg, 'text') === 'string') md += `${msg.text}\n\n`;
      else if (content !== undefined) md += fence('unhandled content shape', jsonSafe(content));
      md += '---\n\n';
    }
    return md.replace(/\n{4,}/g, '\n\n\n');
  }

  // ---------------------- Fetch loop ------------------------
  const raw = [], failures = [];
  let mdAll = '';
  const stamp = new Date().toISOString();
  for (let i = 0; i < convos.length; i++) {
    const id = pick(convos[i], 'uuid', 'id');
    const title = pick(convos[i], 'name', 'title') || id;
    try {
      const data = await api(`${ORG}/chat_conversations/${id}?tree=true&rendering_mode=messages&render_all_tools=true`);
      raw.push(data);
      mdAll += renderConversation(data) + '\n\n\n';
      console.log(`[batch] (${i + 1}/${convos.length}) ok: ${title}`);
    } catch (e) {
      failures.push({ id, title, error: e.message });
      console.warn(`[batch] (${i + 1}/${convos.length}) FAILED: ${title} — ${e.message}`);
    }
    await sleep(DELAY_MS);
  }

  // ------------------------ Manifest ------------------------
  const manifest = {
    exported_at: stamp, org: orgId, project: projectId,
    requested: convos.length, fetched: raw.length, failed: failures.length, failures,
    conversations: raw.map(d => ({
      id: pick(d, 'uuid', 'id'),
      title: pick(d, 'name', 'title'),
      messages: (pick(d, 'chat_messages', 'messages') || []).length,
    })),
  };
  console.log('[batch] manifest:', manifest);

  const slug = `claude_project_${projectId.slice(0, 8)}_${stamp.slice(0, 10)}`;
  if (OUTPUT === 'json' || OUTPUT === 'both') {
    download(`${slug}.json`, JSON.stringify({ manifest, conversations: raw }, null, 2), 'application/json');
    await sleep(300);
  }
  if (OUTPUT === 'markdown' || OUTPUT === 'both') {
    const toc = manifest.conversations.map((c, i) => `${i + 1}. ${c.title} (${c.messages} msgs)`).join('\n');
    const header = `# Project export\n\n*Exported ${stamp}*  \n*Project: ${projectId}*  \n` +
      `*${raw.length} conversations, ${failures.length} failed*\n\n## Contents\n\n${toc}\n\n---\n\n`;
    download(`${slug}.md`, header + mdAll, 'text/markdown');
  }
  console.log(`[batch] done. fetched ${raw.length}/${convos.length}` +
              (failures.length ? `, ${failures.length} failed (see manifest.failures)` : ''));
})();

