// claude_project_docs_zip.js
// Paste into DevTools console on the PROJECT page (URL contains /project/<uuid>).
// Downloads the project's knowledge documents as a single .zip.
//
// No external library: the zip is built in-page with a minimal CRC-32 and the
// standard STORED (uncompressed) ZIP layout. Uncompressed is fine for text and,
// crucially, needs no injected script, so Claude.ai's content-security policy
// cannot block it (which a CDN-loaded zip library might).
//
// CONFIRMED vs INFERRED: only the per-conversation endpoint was ever confirmed.
// The project-docs endpoint and its field names are inferred. Run the discovery
// snippet first. Any doc whose text field is not recognized is written to the
// zip as raw JSON instead of being dropped, and a _manifest.json records what
// happened. The zip also contains _raw.json (the untouched API payloads) so the
// archive is lossless regardless of field-name guesses.

(async () => {
  'use strict';

  const PROJECT_ID = '';   // blank = read from the /project/<uuid> URL; set to override

  const pick = (o, ...ks) => { for (const k of ks) if (o && o[k] != null) return o[k]; return undefined; };
  const readCookie = (n) => {
    const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + n + '=([^;]+)'));
    if (!m) return null; try { return decodeURIComponent(m[1]); } catch { return m[1]; }
  };
  const api = async (p) => { const r = await fetch(p, { credentials: 'include', headers: { 'Content-Type': 'application/json' } }); if (!r.ok) throw new Error(`${r.status} on ${p}`); return r.json(); };
  const tryApi = async (p) => { try { return await api(p); } catch (e) { console.warn('[docs]', e.message); return null; } };

  // ---------------- zero-dependency STORED zip ----------------
  function makeZip(files) {
    const table = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1); t[n] = c >>> 0; } return t; })();
    const crc32 = (b) => { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = table[(c ^ b[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
    const enc = new TextEncoder();
    const now = new Date();
    const dosTime = ((now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1)) & 0xFFFF;
    const dosDate = (((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate()) & 0xFFFF;
    const u16 = (v) => new Uint8Array([v & 0xFF, (v >>> 8) & 0xFF]);
    const u32 = (v) => new Uint8Array([v & 0xFF, (v >>> 8) & 0xFF, (v >>> 16) & 0xFF, (v >>> 24) & 0xFF]);

    const chunks = []; const central = []; let offset = 0;
    const put = (a) => { chunks.push(a); offset += a.length; };

    for (const f of files) {
      const name = enc.encode(f.name);
      const data = typeof f.data === 'string' ? enc.encode(f.data) : f.data;
      const crc = crc32(data);
      const at = offset;
      [u32(0x04034b50), u16(20), u16(0x0800), u16(0), u16(dosTime), u16(dosDate),
       u32(crc), u32(data.length), u32(data.length), u16(name.length), u16(0), name].forEach(put);
      put(data);
      central.push([u32(0x02014b50), u16(20), u16(20), u16(0x0800), u16(0), u16(dosTime), u16(dosDate),
        u32(crc), u32(data.length), u32(data.length), u16(name.length), u16(0), u16(0), u16(0), u16(0),
        u32(0), u32(at), name]);
    }
    const cdStart = offset; let cdSize = 0;
    for (const rec of central) for (const p of rec) { put(p); cdSize += p.length; }
    [u32(0x06054b50), u16(0), u16(0), u16(files.length), u16(files.length), u32(cdSize), u32(cdStart), u16(0)].forEach(put);
    return new Blob(chunks, { type: 'application/zip' });
  }

  // ---------------- resolve org + project ----------------
  let orgId = readCookie('lastActiveOrg');
  if (!orgId) { const o = await tryApi('/api/organizations'); orgId = pick((Array.isArray(o) ? o[0] : o) || {}, 'uuid', 'id'); }
  if (!orgId) { alert('Could not determine organization ID.'); return; }
  let projectId = PROJECT_ID || (location.pathname.match(/\/project\/([0-9a-f-]{36})/i) || [])[1];
  if (!projectId) { alert('Run this on the project page (URL must contain /project/<uuid>), or set PROJECT_ID.'); return; }
  const ORG = `/api/organizations/${orgId}`;
  console.log('[docs] org:', orgId, 'project:', projectId);

  // ---------------- fetch docs + project detail ----------------
  const detail = await tryApi(`${ORG}/projects/${projectId}`);
  let docsResp = await tryApi(`${ORG}/projects/${projectId}/docs`);
  let docs = Array.isArray(docsResp) ? docsResp : (pick(docsResp || {}, 'data', 'documents', 'docs') || []);
  if (!docs.length && detail) docs = pick(detail, 'docs', 'documents', 'knowledge', 'files') || [];
  console.log('[docs] documents found:', docs.length);
  if (!docs.length) { alert('No documents found. Run the discovery snippet and check the field names.'); return; }

  // ---------------- assemble files ----------------
  const files = [];
  const used = new Set();
  const uniq = (n) => { let name = n, i = 2; while (used.has(name.toLowerCase())) { const dot = n.lastIndexOf('.'); name = dot > 0 ? `${n.slice(0, dot)}_${i}${n.slice(dot)}` : `${n}_${i}`; i++; } used.add(name.toLowerCase()); return name; };
  const manifest = { exported_at: new Date().toISOString(), org: orgId, project: projectId, count: docs.length, files: [] };

  for (let i = 0; i < docs.length; i++) {
    const d = docs[i];
    let name = pick(d, 'file_name', 'filename', 'name', 'title') || `doc_${i}`;
    name = name.replace(/[\/\\]/g, '_');
    let content = pick(d, 'content', 'text', 'extracted_content', 'data', 'body');
    // per-doc content fetch if the list item lacks it
    if (typeof content !== 'string') {
      const id = pick(d, 'uuid', 'id');
      if (id) { const full = await tryApi(`${ORG}/projects/${projectId}/docs/${id}`); if (full) content = pick(full, 'content', 'text', 'extracted_content', 'data', 'body'); }
    }
    if (typeof content === 'string') {
      const fn = uniq(name);
      files.push({ name: fn, data: content });
      manifest.files.push({ source: name, written: fn, chars: content.length, mode: 'text' });
    } else {
      const fn = uniq((name.includes('.') ? name.slice(0, name.lastIndexOf('.')) : name) + '.json');
      files.push({ name: fn, data: JSON.stringify(d, null, 2) });
      manifest.files.push({ source: name, written: fn, mode: 'raw-json (no text field recognized)' });
    }
  }

  // project custom instructions (flagged earlier as easily lost in exports)
  const instr = detail && pick(detail, 'prompt', 'instructions', 'custom_instructions', 'description');
  if (typeof instr === 'string' && instr.trim()) {
    const fn = uniq('_project_instructions.md');
    files.push({ name: fn, data: instr });
    manifest.files.push({ source: '(project custom instructions)', written: fn, chars: instr.length, mode: 'text' });
  }

  // lossless raw payloads + manifest
  files.push({ name: '_raw.json', data: JSON.stringify({ project_detail: detail, docs_response: docsResp }, null, 2) });
  files.push({ name: '_manifest.json', data: JSON.stringify(manifest, null, 2) });
  console.log('[docs] manifest:', manifest);

  // ---------------- download ----------------
  const blob = makeZip(files);
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `claude_project_${projectId.slice(0, 8)}_docs_${new Date().toISOString().slice(0, 10)}.zip`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  console.log(`[docs] done: ${files.length} entries (${docs.length} documents + instructions + raw + manifest) -> ${a.download}`);
})();

