  if (!docs.length && detail) docs = pick(detail, 'docs', 'documents', 'knowledge', 'files') || [];
  console.log('[docs] documents found:', docs.length);
  if (!docs.length) { alert('No documents found. Run the discovery snippet and check the field names.'); return; }

  // ---------------- assemble files ----------------
  const files = [];
  const used = new Set();
  const uniq = (n) => { let name = n, i = 2; while (used.has(name.toLowerCase())) { const dot = n.lastIndexOf('.'); name = dot > 0 ? `${n.slice(0, dot)}_${i}${n.slice(dot)}` : `${n}_${i}`; i++; } used.add(name.toLowerCase()); return name; };
  const manifest = { exported_at: new Date().toISOString(), org: orgId, project: projectId, count: docs.length, files: [] };

  for (let i = 0; i < docs.length; i++) {
    const d = docs[i];
    let name = pick(d, 'file_name', 'filename', 'name', 'title') || `doc_${i}`;
    name = name.replace(/[\/\\]/g, '_');
    let content = pick(d, 'content', 'text', 'extracted_content', 'data', 'body');
    // per-doc content fetch if the list item lacks it
    if (typeof content !== 'string') {
      const id = pick(d, 'uuid', 'id');
      if (id) { const full = await tryApi(`${ORG}/projects/${projectId}/docs/${id}`); if (full) content = pick(full, 'content', 'text', 'extracted_content', 'data', 'body'); }
    }
    if (typeof content === 'string') {
      const fn = uniq(name);
      files.push({ name: fn, data: content });
      manifest.files.push({ source: name, written: fn, chars: content.length, mode: 'text' });
    } else {
      const fn = uniq((name.includes('.') ? name.slice(0, name.lastIndexOf('.')) : name) + '.json');
      files.push({ name: fn, data: JSON.stringify(d, null, 2) });
      manifest.files.push({ source: name, written: fn, mode: 'raw-json (no text field recognized)' });
    }
  }

  // project custom instructions (flagged earlier as easily lost in exports)
  const instr = detail && pick(detail, 'prompt', 'instructions', 'custom_instructions', 'description');
  if (typeof instr === 'string' && instr.trim()) {
    const fn = uniq('_project_instructions.md');
    files.push({ name: fn, data: instr });
    manifest.files.push({ source: '(project custom instructions)', written: fn, chars: instr.length, mode: 'text' });
  }

  // lossless raw payloads + manifest
  files.push({ name: '_raw.json', data: JSON.stringify({ project_detail: detail, docs_response: docsResp }, null, 2) });
  files.push({ name: '_manifest.json', data: JSON.stringify(manifest, null, 2) });
  console.log('[docs] manifest:', manifest);

  // ---------------- download ----------------
  const blob = makeZip(files);
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `claude_project_${projectId.slice(0, 8)}_docs_${new Date().toISOString().slice(0, 10)}.zip`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  console.log(`[docs] done: ${files.length} entries (${docs.length} documents + instructions + raw + manifest) -> ${a.download}`);
})();
